with exploded as (select id, customer_id, coupon_codes, line.product_id, line.qty, line.price, line.promo from carts lateral view outer explode(items) e as line) select customer_id, case when qty >= 5 then 'HIGH' else 'LOW' end as qty_tier, min(price) as min_price, count_if(promo = 'SPRING10') as spring10_events, round(avg(qty), 2) as avg_qty, sum(case when promo = 'SPRING10' then price else 0 end) as spring10_price, count(*) filter (where promo = 'BUNDLE') as bundle_rows from exploded group by 1, 2 order by bundle_rows asc nulls first
